def list_business_domains():
    return [dict(item, capabilities=list(item["capabilities"])) for item in BUSINESS_DOMAINS]

def get_business_domain(domain_id):
    key = domain_id.strip().casefold()
    return next((dict(item, capabilities=list(item["capabilities"])) for item in BUSINESS_DOMAINS if item["domain_id"].casefold() == key), None)

def validate_business_domains(core_domain_ids=None):
    valid_core_ids = set(core_domain_ids) if core_domain_ids is not None else {
        item["domain_id"] for item in list_domains()
    }
    ids = [item["domain_id"] for item in BUSINESS_DOMAINS]
    mapped = {item["core_domain_id"] for item in BUSINESS_DOMAINS}
    missing = sorted(mapped - valid_core_ids)
    return {
        "valid": len(ids) == len(set(ids)) and not missing,
        "count": len(ids),
        "unique_ids": len(ids) == len(set(ids)),
        "missing_core_domain_ids": missing,
    }
